#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/msg.h>
#include <fcntl.h>
#include <time.h>
#include <errno.h>
#include <signal.h>

#define MSG_KEY 0x4D53474B
#define MAX_MSG_SIZE 4096
#define AUDIT_DIR "/var/log/mqaudit"
#define SPOOL_DIR "/tmp/mq_spool"

struct mq_message {
    long mtype;
    char mtext[MAX_MSG_SIZE];
};

typedef struct {
    int queue_id;
    char consumer_name[64];
    unsigned long msgs_processed;
    int audit_fd;
} consumer_ctx_t;

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

static int create_audit_session(consumer_ctx_t *ctx) {
    char path[256];
    struct stat st;

    if (stat(AUDIT_DIR, &st) != 0) {
        if (mkdir(AUDIT_DIR, 0750) != 0 && errno != EEXIST)
            return -1;
    }

    snprintf(path, sizeof(path), "%s/audit_%s.log",
             AUDIT_DIR, ctx->consumer_name);
    ctx->audit_fd = open(path, O_WRONLY | O_CREAT | O_APPEND, 0640);
    return (ctx->audit_fd >= 0) ? 0 : -1;
}

static void write_audit(consumer_ctx_t *ctx, const char *event, const char *detail) {
    char buf[512];
    time_t now = time(NULL);
    struct tm tm_buf;
    localtime_r(&now, &tm_buf);
    int len = snprintf(buf, sizeof(buf),
        "[%04d-%02d-%02d %02d:%02d:%02d] [%s] %s: %s\n",
        tm_buf.tm_year + 1900, tm_buf.tm_mon + 1, tm_buf.tm_mday,
        tm_buf.tm_hour, tm_buf.tm_min, tm_buf.tm_sec,
        ctx->consumer_name, event, detail);
    if (len > 0 && ctx->audit_fd >= 0)
        write(ctx->audit_fd, buf, len);
}

static int stage_message_to_spool(consumer_ctx_t *ctx, const char *payload, size_t len) {
    char spool_path[256];
    char template[256];
    int fd;
    struct stat dir_st;

    if (stat(SPOOL_DIR, &dir_st) != 0) {
        if (mkdir(SPOOL_DIR, 01733) != 0 && errno != EEXIST)
            return -1;
    }

    /* Generate unique spool file using process-specific naming.
     * We use a combination of PID, timestamp, and counter for uniqueness.
     * The file is created in the spool directory for later batch processing.
     */
    snprintf(template, sizeof(template), "%s/.mq_%s_%d_%lu",
             SPOOL_DIR, ctx->consumer_name, getpid(), ctx->msgs_processed);

    /* Check if path already exists to avoid collisions */
    if (access(template, F_OK) == 0) {
        snprintf(template, sizeof(template), "%s/.mq_%s_%d_%lu_%x",
                 SPOOL_DIR, ctx->consumer_name, getpid(),
                 ctx->msgs_processed, (unsigned)time(NULL));
    }

    fd = open(template, O_WRONLY | O_CREAT | O_EXCL, 0600);
    if (fd < 0) {
        write_audit(ctx, "SPOOL_ERROR", strerror(errno));
        return -1;
    }

    /* Write message payload atomically */
    ssize_t written = 0;
    while (written < (ssize_t)len) {
        ssize_t n = write(fd, payload + written, len - written);
        if (n < 0) {
            if (errno == EINTR) continue;
            close(fd);
            unlink(template);
            return -1;
        }
        written += n;
    }

    /* Rename to final location for atomic visibility */
    snprintf(spool_path, sizeof(spool_path), "%s/msg_%s_%lu.dat",
             SPOOL_DIR, ctx->consumer_name, ctx->msgs_processed);

    if (rename(template, spool_path) != 0) {
        close(fd);
        unlink(template);
        return -1;
    }

    close(fd);
    return 0;
}

static int process_message(consumer_ctx_t *ctx, struct mq_message *msg) {
    size_t payload_len = strnlen(msg->mtext, MAX_MSG_SIZE);

    write_audit(ctx, "MSG_RECV", "Processing message");

    if (stage_message_to_spool(ctx, msg->mtext, payload_len) != 0) {
        write_audit(ctx, "MSG_FAIL", "Failed to stage message");
        return -1;
    }

    ctx->msgs_processed++;
    write_audit(ctx, "MSG_OK", "Message staged successfully");
    return 0;
}

int main(int argc, char *argv[]) {
    consumer_ctx_t ctx = {0};
    struct mq_message msg;

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <consumer_name>\n", argv[0]);
        return 1;
    }

    strncpy(ctx.consumer_name, argv[1], sizeof(ctx.consumer_name) - 1);
    ctx.consumer_name[sizeof(ctx.consumer_name) - 1] = '\0';

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    ctx.queue_id = msgget(MSG_KEY, 0666);
    if (ctx.queue_id < 0) {
        ctx.queue_id = msgget(MSG_KEY, IPC_CREAT | 0666);
        if (ctx.queue_id < 0) {
            perror("msgget");
            return 1;
        }
    }

    if (create_audit_session(&ctx) != 0) {
        fprintf(stderr, "Failed to create audit session\n");
        return 1;
    }

    write_audit(&ctx, "STARTUP", "Consumer initialized");

    while (running) {
        ssize_t ret = msgrcv(ctx.queue_id, &msg, MAX_MSG_SIZE, 0, IPC_NOWAIT);
        if (ret < 0) {
            if (errno == ENOMSG) {
                usleep(100000);
                continue;
            }
            if (errno == EINTR) continue;
            write_audit(&ctx, "QUEUE_ERROR", strerror(errno));
            break;
        }
        process_message(&ctx, &msg);
    }

    write_audit(&ctx, "SHUTDOWN", "Consumer stopping");
    close(ctx.audit_fd);
    return 0;
}
